#include "kernel_operator.h"

using namespace AscendC;

struct ForeachAddcdivListTiling {
    int64_t totalLength;
    int64_t tileLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
};

template <typename T>
class KernelForeachAddcdivList {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
        GM_ADDR scalarsGm, GM_ADDR yGm, GM_ADDR tilingGm,
        AscendC::TPipe *pipe)
    {
        pipe_ = pipe;
        CopyTiling(&tiling_, tilingGm);

        x1Global_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x1Gm), tiling_.totalLength);
        x2Global_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x2Gm), tiling_.totalLength);
        x3Global_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x3Gm), tiling_.totalLength);
        scalarsGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(scalarsGm), tiling_.totalLength);
        yGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yGm), tiling_.totalLength);

        tileLength_ = static_cast<int64_t>(tiling_.tileLength);

        // VECIN queues for 4 inputs (depth=0)
        pipe_->InitBuffer(inQueueX1_, 0, tileLength_ * sizeof(T));
        pipe_->InitBuffer(inQueueX2_, 0, tileLength_ * sizeof(T));
        pipe_->InitBuffer(inQueueX3_, 0, tileLength_ * sizeof(T));
        pipe_->InitBuffer(inQueueS_, 0, tileLength_ * sizeof(T));
        // VECOUT queue for output (depth=0)
        pipe_->InitBuffer(outQueue_, 0, tileLength_ * sizeof(T));
        // TBuf for fp32 intermediate computation (VECCALC)
        pipe_->InitBuffer(tmpBuf1_, tileLength_ * sizeof(float));
        pipe_->InitBuffer(tmpBuf2_, tileLength_ * sizeof(float));
        pipe_->InitBuffer(tmpBuf3_, tileLength_ * sizeof(float));
        pipe_->InitBuffer(tmpBuf4_, tileLength_ * sizeof(float));
        pipe_->InitBuffer(tmpBuf5_, tileLength_ * sizeof(float));
        pipe_->InitBuffer(tmpBuf6_, tileLength_ * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t blockIdx = GetBlockIdx();
        int64_t blockStart, blockEnd;

        if (blockIdx < tiling_.formerNum) {
            blockStart = blockIdx * tiling_.formerLength;
            blockEnd = blockStart + tiling_.formerLength;
        } else if (blockIdx == tiling_.formerNum && tiling_.tailNum > 0) {
            blockStart = tiling_.formerNum * tiling_.formerLength;
            blockEnd = blockStart + tiling_.tailLength;
        } else {
            return;
        }

        int64_t totalBlockElements = blockEnd - blockStart;
        int64_t numTiles = (totalBlockElements + tileLength_ - 1) / tileLength_;

        for (int64_t t = 0; t < numTiles; ++t) {
            int64_t curStart = blockStart + t * tileLength_;
            int64_t curLength = tileLength_;
            if (curStart + curLength > blockEnd) {
                curLength = blockEnd - curStart;
            }
            CopyIn(curStart, curLength);
            Compute(curLength);
            CopyOut(curStart, curLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t start, int64_t length)
    {
        int64_t byteLength = static_cast<int64_t>(length * sizeof(T));

        LocalTensor<T> x1Local = inQueueX1_.AllocTensor<T>();
        LocalTensor<T> x2Local = inQueueX2_.AllocTensor<T>();
        LocalTensor<T> x3Local = inQueueX3_.AllocTensor<T>();
        LocalTensor<T> sLocal = inQueueS_.AllocTensor<T>();

        DataCopyPadExtParams<T> padParams = {false, 0, 0, 0};
        DataCopyParams copyParams = {1, static_cast<uint32_t>(byteLength), 0, 0};

        DataCopyPad(x1Local, x1Global_[start], copyParams, padParams);
        DataCopyPad(x2Local, x2Global_[start], copyParams, padParams);
        DataCopyPad(x3Local, x3Global_[start], copyParams, padParams);
        DataCopyPad(sLocal, scalarsGlobal_[start], copyParams, padParams);

        inQueueX1_.EnQue(x1Local);
        inQueueX2_.EnQue(x2Local);
        inQueueX3_.EnQue(x3Local);
        inQueueS_.EnQue(sLocal);
    }

    __aicore__ inline void Compute(int64_t length)
    {
        LocalTensor<T> x1Local = inQueueX1_.DeQue<T>();
        LocalTensor<T> x2Local = inQueueX2_.DeQue<T>();
        LocalTensor<T> x3Local = inQueueX3_.DeQue<T>();
        LocalTensor<T> sLocal  = inQueueS_.DeQue<T>();

        LocalTensor<float> fBuf1 = tmpBuf1_.Get<float>();
        LocalTensor<float> fBuf2 = tmpBuf2_.Get<float>();
        LocalTensor<float> fBuf3 = tmpBuf3_.Get<float>();
        LocalTensor<float> fBuf4 = tmpBuf4_.Get<float>();
        LocalTensor<float> fBuf5 = tmpBuf5_.Get<float>();
        LocalTensor<float> fBuf6 = tmpBuf6_.Get<float>();

        LocalTensor<T> yLocal = outQueue_.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: direct computation
            // fBuf2 = X2 / X3
            Div(fBuf2, x2Local, x3Local, length);
            // fBuf2 = fBuf2 * Scalars
            Mul(fBuf2, fBuf2, sLocal, length);
            // yLocal = X1 + fBuf2
            Add(yLocal, x1Local, fBuf2, length);
        } else {
            // FP16/BF16 path: cast to fp32, compute, cast back
            // Cast inputs to fp32
            Cast(fBuf1, x1Local, RoundMode::CAST_NONE, length);
            Cast(fBuf2, x2Local, RoundMode::CAST_NONE, length);
            Cast(fBuf3, x3Local, RoundMode::CAST_NONE, length);
            Cast(fBuf4, sLocal, RoundMode::CAST_NONE, length);

            // fBuf5 = X2_fp32 / X3_fp32
            Div(fBuf5, fBuf2, fBuf3, length);
            // fBuf5 = fBuf5 * Scalars_fp32
            Mul(fBuf5, fBuf5, fBuf4, length);
            // fBuf6 = X1_fp32 + fBuf5
            Add(fBuf6, fBuf1, fBuf5, length);

            // Cast result back to original dtype
            Cast(yLocal, fBuf6, RoundMode::CAST_NONE, length);
        }

        outQueue_.EnQue<T>(yLocal);

        inQueueX1_.FreeTensor(x1Local);
        inQueueX2_.FreeTensor(x2Local);
        inQueueX3_.FreeTensor(x3Local);
        inQueueS_.FreeTensor(sLocal);
    }

    __aicore__ inline void CopyOut(int64_t start, int64_t length)
    {
        int64_t byteLength = static_cast<int64_t>(length * sizeof(T));
        DataCopyParams copyParams = {1, static_cast<uint32_t>(byteLength), 0, 0};

        LocalTensor<T> yLocal = outQueue_.DeQue<T>();
        DataCopyPad(yGlobal_[start], yLocal, copyParams);
        outQueue_.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe *pipe_;
    ForeachAddcdivListTiling tiling_;
    int64_t tileLength_;

    GlobalTensor<T> x1Global_;
    GlobalTensor<T> x2Global_;
    GlobalTensor<T> x3Global_;
    GlobalTensor<T> scalarsGlobal_;
    GlobalTensor<T> yGlobal_;

    TQue<QuePosition::VECIN, 0>  inQueueX1_;
    TQue<QuePosition::VECIN, 0>  inQueueX2_;
    TQue<QuePosition::VECIN, 0>  inQueueX3_;
    TQue<QuePosition::VECIN, 0>  inQueueS_;
    TQue<QuePosition::VECOUT, 0> outQueue_;

    TBuf<QuePosition::VECCALC> tmpBuf1_;
    TBuf<QuePosition::VECCALC> tmpBuf2_;
    TBuf<QuePosition::VECCALC> tmpBuf3_;
    TBuf<QuePosition::VECCALC> tmpBuf4_;
    TBuf<QuePosition::VECCALC> tmpBuf5_;
    TBuf<QuePosition::VECCALC> tmpBuf6_;
};

extern "C" __global__ __aicore__ void foreach_addcdiv_list_fp16(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm, GM_ADDR tilingGm)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    AscendC::TPipe pipe;
    KernelForeachAddcdivList<half> kernel;
    kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm, tilingGm, &pipe);
    kernel.Process();
}

extern "C" __global__ __aicore__ void foreach_addcdiv_list_fp32(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm, GM_ADDR tilingGm)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
