#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

// cmake auto-generates these aclrtlaunch headers
#include "aclrtlaunch_foreach_addcdiv_list_fp16.h"
#include "aclrtlaunch_foreach_addcdiv_list_fp32.h"
#include "aclrtlaunch_foreach_addcdiv_list_bf16.h"

namespace ascend_kernel {

namespace {

struct ForeachAddcdivListTiling {
    int64_t totalLength;
    int64_t tileLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
};

constexpr int64_t kBufferCoefficient = 48;   // Bytes per element for UB budget
constexpr int64_t kCacheLineBytes = 512;     // Cache line alignment

} // anonymous namespace

at::Tensor foreach_addcdiv_list(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &x3,
    const at::Tensor &scalars,
    const at::Tensor &y)
{
    TORCH_CHECK(x1.is_contiguous(), "x1 must be contiguous");
    TORCH_CHECK(x2.is_contiguous(), "x2 must be contiguous");
    TORCH_CHECK(x3.is_contiguous(), "x3 must be contiguous");
    TORCH_CHECK(scalars.is_contiguous(), "scalars must be contiguous");

    int64_t totalLength = x1.numel();
    TORCH_CHECK(x2.numel() == totalLength, "x1 and x2 must have same numel");
    TORCH_CHECK(x3.numel() == totalLength, "x1 and x3 must have same numel");
    TORCH_CHECK(scalars.numel() == totalLength, "x1 and scalars must have same numel");

    auto dtype = x1.scalar_type();

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    uint64_t ubSizeVal;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
    int64_t ubSize = static_cast<int64_t>(ubSizeVal);

    int64_t dtypeSize = static_cast<int64_t>(c10::elementSize(dtype));

    // Compute tile length based on UB budget
    // BUFFER_NUM = 1 for TQue depth=0 (single buffer, no double buffering)
    constexpr int64_t bufferNum = 1;
    int64_t tileLength = (kBufferCoefficient * ubSize) / (dtypeSize * bufferNum) / 32 * 32;
    if (tileLength <= 0) {
        tileLength = 512;
    }

    // Block-level compute: split total elements across cores
    // Align to cache line boundary
    int64_t clAlign = kCacheLineBytes / static_cast<int64_t>(dtypeSize);
    int64_t coreAlign = ((totalLength + coreNum - 1) / coreNum + clAlign - 1) / clAlign * clAlign;

    int64_t formerNum = totalLength / coreAlign;
    int64_t formerLength = coreAlign;
    int64_t tailNum = (totalLength % coreAlign == 0) ? 0 : 1;
    int64_t tailLength = (totalLength % coreAlign);

    // Total blocks to launch
    int64_t blockDim = formerNum + tailNum;

    // Create tiling struct as left value
    ForeachAddcdivListTiling tilingData;
    tilingData.totalLength = totalLength;
    tilingData.tileLength = tileLength;
    tilingData.formerNum = formerNum;
    tilingData.formerLength = formerLength;
    tilingData.tailNum = tailNum;
    tilingData.tailLength = tailLength;

    // All left-value variables for EXEC_KERNEL_CMD
    int64_t blockDimLv = blockDim;
    auto x1Contig = x1.contiguous();
    auto x2Contig = x2.contiguous();
    auto x3Contig = x3.contiguous();
    auto scalarsContig = scalars.contiguous();
    auto yResult = at::empty_like(x1Contig);

    if (dtype == at::kFloat) {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_fp32, blockDimLv,
                        x1Contig, x2Contig, x3Contig, scalarsContig, yResult, tilingData);
    } else if (dtype == at::kHalf) {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_fp16, blockDimLv,
                        x1Contig, x2Contig, x3Contig, scalarsContig, yResult, tilingData);
    } else if (dtype == at::kBFloat16) {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_bf16, blockDimLv,
                        x1Contig, x2Contig, x3Contig, scalarsContig, yResult, tilingData);
    } else {
        TORCH_CHECK(false, "Unsupported dtype: ", dtype);
    }

    return yResult;
}

} // namespace ascend_kernel
