#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// GM <-> UB helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------

template <typename T>
class KernelForeachAddcdivList {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
        GM_ADDR scalarsGm, GM_ADDR yGm,
        int32_t totalLength, int32_t tileLength,
        int32_t blockStart, int32_t blockEnd)
    {
        totalLen_ = totalLength;
        tileLen_ = tileLength;
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x1Gm), totalLen_);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x2Gm), totalLen_);
        x3GM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x3Gm), totalLen_);
        sGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(scalarsGm), totalLen_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yGm), totalLen_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQueueX1_, BUFFER_NUM, tileLen_ * sizeof(T));
            pipe.InitBuffer(inQueueX2_, BUFFER_NUM, tileLen_ * sizeof(T));
            pipe.InitBuffer(inQueueX3_, BUFFER_NUM, tileLen_ * sizeof(T));
            pipe.InitBuffer(inQueueS_,  BUFFER_NUM, tileLen_ * sizeof(T));
            pipe.InitBuffer(outQueue_,   BUFFER_NUM, tileLen_ * sizeof(T));

            if constexpr (!std::is_same_v<T, float>) {
                pipe.InitBuffer(castX1Buf_,   tileLen_ * sizeof(float));
                pipe.InitBuffer(castX2Buf_,   tileLen_ * sizeof(float));
                pipe.InitBuffer(castX3Buf_,   tileLen_ * sizeof(float));
                pipe.InitBuffer(castSBuf_,    tileLen_ * sizeof(float));
                pipe.InitBuffer(tmpCalcBuf1_, tileLen_ * sizeof(float));
                pipe.InitBuffer(tmpCalcBuf2_, tileLen_ * sizeof(float));
            } else {
                pipe.InitBuffer(tmpCalcBuf1_, tileLen_ * sizeof(float));
                pipe.InitBuffer(tmpCalcBuf2_, tileLen_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t curStart = blockStart_;
            while (curStart < blockEnd_) {
                int32_t curLen = tileLen_;
                if (curStart + curLen > blockEnd_) {
                    curLen = blockEnd_ - curStart;
                }
                CopyIn(curStart, curLen);
                Compute(curLen);
                CopyOut(curStart, curLen);
                curStart += curLen;
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t start, int32_t length)
    {
        x1InLocal_ = inQueueX1_.AllocTensor<T>();
        x2InLocal_ = inQueueX2_.AllocTensor<T>();
        x3InLocal_ = inQueueX3_.AllocTensor<T>();
        sInLocal_  = inQueueS_.AllocTensor<T>();

        LoadGmToUb(x1InLocal_, x1GM_[start], static_cast<uint32_t>(length));
        LoadGmToUb(x2InLocal_, x2GM_[start], static_cast<uint32_t>(length));
        LoadGmToUb(x3InLocal_, x3GM_[start], static_cast<uint32_t>(length));
        LoadGmToUb(sInLocal_,  sGM_[start],  static_cast<uint32_t>(length));

        inQueueX1_.EnQue(x1InLocal_);
        inQueueX2_.EnQue(x2InLocal_);
        inQueueX3_.EnQue(x3InLocal_);
        inQueueS_.EnQue(sInLocal_);
    }

    __aicore__ inline void Compute(int32_t length)
    {
        x1InLocal_ = inQueueX1_.DeQue<T>();
        x2InLocal_ = inQueueX2_.DeQue<T>();
        x3InLocal_ = inQueueX3_.DeQue<T>();
        sInLocal_  = inQueueS_.DeQue<T>();
        yOutLocal_ = outQueue_.AllocTensor<T>();

        if constexpr (std::is_same_v<T, float>) {
            auto t1 = tmpCalcBuf1_.Get<float>();
            auto t2 = tmpCalcBuf2_.Get<float>();

            AscendC::Div(t1, x2InLocal_, x3InLocal_, length);
            AscendC::Mul(t1, t1, sInLocal_, length);
            AscendC::Add(yOutLocal_, x1InLocal_, t1, length);
        } else {
            auto x1f = castX1Buf_.Get<float>();
            auto x2f = castX2Buf_.Get<float>();
            auto x3f = castX3Buf_.Get<float>();
            auto sf  = castSBuf_.Get<float>();
            auto t1  = tmpCalcBuf1_.Get<float>();
            auto t2  = tmpCalcBuf2_.Get<float>();

            AscendC::Cast(x1f, x1InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(x2f, x2InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(x3f, x3InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(sf,  sInLocal_,  AscendC::RoundMode::CAST_NONE, length);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Div(t1, x2f, x3f, length);
            AscendC::Mul(t1, t1, sf, length);
            AscendC::Add(t2, x1f, t1, length);

            if constexpr (std::is_same_v<T, bfloat16_t>) {
                AscendC::Cast(yOutLocal_, t2, AscendC::RoundMode::CAST_ROUND, length);
            } else {
                AscendC::Cast(yOutLocal_, t2, AscendC::RoundMode::CAST_NONE, length);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }

        outQueue_.EnQue<T>(yOutLocal_);

        inQueueX1_.FreeTensor(x1InLocal_);
        inQueueX2_.FreeTensor(x2InLocal_);
        inQueueX3_.FreeTensor(x3InLocal_);
        inQueueS_.FreeTensor(sInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t start, int32_t length)
    {
        yOutLocal_ = outQueue_.DeQue<T>();
        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(length));
        outQueue_.FreeTensor(yOutLocal_);
    }

private:
    AscendC::TPipe pipe;
    int32_t totalLen_;
    int32_t tileLen_;
    int32_t blockStart_;
    int32_t blockEnd_;

    AscendC::GlobalTensor<T> x1GM_;
    AscendC::GlobalTensor<T> x2GM_;
    AscendC::GlobalTensor<T> x3GM_;
    AscendC::GlobalTensor<T> sGM_;
    AscendC::GlobalTensor<T> yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX1_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX2_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX3_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueS_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> castX1Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castX2Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castX3Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castSBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpCalcBuf1_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpCalcBuf2_;

    AscendC::LocalTensor<T> x1InLocal_;
    AscendC::LocalTensor<T> x2InLocal_;
    AscendC::LocalTensor<T> x3InLocal_;
    AscendC::LocalTensor<T> sInLocal_;
    AscendC::LocalTensor<T> yOutLocal_;
};

