{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    KernelForeachAddcdivList<float> kernel;
    kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
