#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_addcdiv_list_fp16.h"
#include "aclrtlaunch_foreach_addcdiv_list_fp32.h"
#include "aclrtlaunch_foreach_addcdiv_list_bf16.h"

namespace ascend_kernel {

constexpr int64_t kBufferCoefficient = 48;
constexpr int64_t kCacheLineSize = 512;
constexpr int32_t kDefaultCores = 20;

at::Tensor foreach_addcdiv_list(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &x3,
    const at::Tensor &scalars)
{
    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
                   x1.scalar_type() == at::kBFloat16,
        "unsupported dtype");
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type() &&
                   x1.scalar_type() == x3.scalar_type() &&
                   x1.scalar_type() == scalars.scalar_type(),
        "all inputs must have the same dtype");
    TORCH_CHECK(x1.numel() == x2.numel(), "x1, x2: numel mismatch");
    TORCH_CHECK(x1.numel() == x3.numel(), "x1, x3: numel mismatch");
    TORCH_CHECK(x1.numel() == scalars.numel(), "x1, scalars: numel mismatch");

    auto x1Contig = x1.contiguous();
    auto x2Contig = x2.contiguous();
    auto x3Contig = x3.contiguous();
    auto sContig = scalars.contiguous();

    auto dtype = x1.scalar_type();

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum64 = ascendcPlatform->GetCoreNumAiv();
    int32_t coreNum = static_cast<int32_t>(std::min<int64_t>(coreNum64, kDefaultCores));

    uint64_t ubSizeVal;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
    int64_t ubSize = static_cast<int64_t>(ubSizeVal);

    int64_t dtypeSize = static_cast<int64_t>(c10::elementSize(dtype));

    // Tile size: UB budget / (4 inputs + 1 output) for fp16 (with cast to fp32)
    // For fp32: 5 buffers * 4 bytes = 20 bytes per element
    // For fp16: 5 buffers * 2 bytes = 10 per element ... but cast buf is fp32
    // Conservative: use kBufferCoefficient
    int32_t tileLen = static_cast<int32_t>((kBufferCoefficient * ubSize) / dtypeSize);
    tileLen = (tileLen / 32) * 32;
    if (tileLen <= 0) {
        tileLen = 256;
    }
    // Cap max tile length for safety
    if (tileLen > 16384) {
        tileLen = 16384;
    }

    // Block-level partition
    int64_t totalLen = x1Contig.numel();
    int32_t totalLenI32 = static_cast<int32_t>(totalLen);

    // Cache line aligned elements per core
    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
    int32_t elemsPerCore = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
    elemsPerCore = ((elemsPerCore + elemPerCL - 1) / elemPerCL) * elemPerCL;

    int32_t formerNum = static_cast<int32_t>(totalLen / elemsPerCore);
    int32_t formerLen = elemsPerCore;
    int32_t tailLen = static_cast<int32_t>(totalLen % elemsPerCore);
    int32_t tailNum = (tailLen > 0) ? 1 : 0;

    auto yOut = at::empty_like(x1Contig);

    // All values must be left-values for EXEC_KERNEL_CMD
    int32_t blockStart, blockEnd;
    uint32_t blockDim;
    int32_t i;

    if (dtype == at::kFloat) {
        i = 0;
        while (i < formerNum) {
            blockDim = 1;
            blockStart = i * formerLen;
            blockEnd = blockStart + formerLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_fp32, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
            i++;
        }
        if (tailNum > 0) {
            blockDim = 1;
            blockStart = formerNum * formerLen;
            blockEnd = blockStart + tailLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_fp32, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
        }
    } else if (dtype == at::kHalf) {
        i = 0;
        while (i < formerNum) {
            blockDim = 1;
            blockStart = i * formerLen;
            blockEnd = blockStart + formerLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_fp16, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
            i++;
        }
        if (tailNum > 0) {
            blockDim = 1;
            blockStart = formerNum * formerLen;
            blockEnd = blockStart + tailLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_fp16, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
        }
    } else {  // bfloat16
        i = 0;
        while (i < formerNum) {
            blockDim = 1;
            blockStart = i * formerLen;
            blockEnd = blockStart + formerLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_bf16, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
            i++;
        }
        if (tailNum > 0) {
            blockDim = 1;
            blockStart = formerNum * formerLen;
            blockEnd = blockStart + tailLen;
            EXEC_KERNEL_CMD(foreach_addcdiv_list_bf16, blockDim,
                            x1Contig, x2Contig, x3Contig, sContig, yOut,
                            totalLenI32, tileLen, blockStart, blockEnd);
        }
    }

    return yOut;
}

}  // namespace ascend_kernel
