namespace ascend_kernel {

constexpr int64_t kCacheLineSize = 512;
constexpr int32_t kDefaultCores = 20;

at::Tensor foreach_addcdiv_list(
    const at::Tensor &x1,
    const at::Tensor &x2,
    const at::Tensor &x3,
    const at::Tensor &scalars)
{
    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
                   x1.scalar_type() == at::kBFloat16,
        "unsupported dtype");
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type() &&
                   x1.scalar_type() == x3.scalar_type() &&
                   x1.scalar_type() == scalars.scalar_type(),
        "all inputs must have the same dtype");
    TORCH_CHECK(x1.numel() == x2.numel(), "numel mismatch");
    TORCH_CHECK(x1.numel() == x3.numel(), "numel mismatch");
    TORCH_CHECK(x1.numel() == scalars.numel(), "numel mismatch");

    auto x1Contig = x1.contiguous();
    auto x2Contig = x2.contiguous();
    auto x3Contig = x3.contiguous();
    auto sContig = scalars.contiguous();

    auto dtype = x1.scalar_type();

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum64 = ascendcPlatform->GetCoreNumAiv();
    int32_t coreNum = static_cast<int32_t>(std::min<int64_t>(coreNum64, kDefaultCores));

    uint64_t ubSizeVal;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
    int64_t ubSize = static_cast<int64_t>(ubSizeVal);
    int64_t dtypeSize = static_cast<int64_t>(c10::elementSize(dtype));

    // Tile size: use 64KB for data buffers (4 inputs + 1 output + cast bufs)
    constexpr int64_t kDataUbBudget = 65536;
    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / (dtypeSize * 5));
    tileLen = (tileLen / 32) * 32;
    if (tileLen < 32) {
        tileLen = 32;
    }
    if (tileLen > 8192) {
        tileLen = 8192;
    }

    int64_t totalLen = x1Contig.numel();
    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
    auto yOut = at::empty_like(x1Contig);

    // Block-level partition with cache line alignment
    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
    int32_t elemsPerCore = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
    elemsPerCore = ((elemsPerCore + elemPerCL - 1) / elemPerCL) * elemPerCL;
    if (elemsPerCore < elemPerCL) {
        elemsPerCore = elemPerCL;
    }

    int32_t formerNumI32 = static_cast<int32_t>(totalLen / elemsPerCore);
    int32_t formerLengthI32 = elemsPerCore;
    int32_t tailLengthI32 = static_cast<int32_t>(totalLen % elemsPerCore);
    int32_t tailNumI32 = (tailLengthI32 > 0) ? 1 : 0;

    // blockDim MUST be uint32_t for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(formerNumI32 + tailNumI32);

    if (dtype == at::kFloat) {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_fp32, blockDim,
                        x1Contig, x2Contig, x3Contig, sContig, yOut,
                        totalLenI32, tileLen,
                        formerNumI32, formerLengthI32, tailNumI32, tailLengthI32);
    } else if (dtype == at::kHalf) {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_fp16, blockDim,
                        x1Contig, x2Contig, x3Contig, sContig, yOut,
                        totalLenI32, tileLen,
                        formerNumI32, formerLengthI32, tailNumI32, tailLengthI32);
    } else {
        EXEC_KERNEL_CMD(foreach_addcdiv_list_bf16, blockDim,
                        x1Contig, x2Contig, x3Contig, sContig, yOut,
                        totalLenI32, tileLen,
                        formerNumI32, formerLengthI32, tailNumI32, tailLengthI32);
    }

    return yOut;
}

