// ForeachAddcdivList kernel: Y = X1 + X2 / X3 * Scalars (elementwise, 1D)
// Adapted from working AddRmsNorm kernel pattern.
// Supports float32, float16, bfloat16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// GM <-> UB helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Main kernel class
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelForeachAddcdivList {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
        GM_ADDR scalarsGm, GM_ADDR yGm,
        int32_t totalLength, int32_t tileLength,
        int32_t formerNum, int32_t formerLength,
        int32_t tailNum, int32_t tailLength)
    {
        totalLen_ = totalLength;
        tileLen_  = tileLength;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailNum_ = tailNum;
        tailLength_ = tailLength;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Gm), totalLen_);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Gm), totalLen_);
        x3GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x3Gm), totalLen_);
        sGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(scalarsGm), totalLen_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalLen_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQueueX1_, BUFFER_NUM, tileLen_ * sizeof(dataType));
            pipe.InitBuffer(inQueueX2_, BUFFER_NUM, tileLen_ * sizeof(dataType));
            pipe.InitBuffer(inQueueX3_, BUFFER_NUM, tileLen_ * sizeof(dataType));
            pipe.InitBuffer(inQueueS_,  BUFFER_NUM, tileLen_ * sizeof(dataType));
            pipe.InitBuffer(outQueue_,   BUFFER_NUM, tileLen_ * sizeof(dataType));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_,  tileLen_ * sizeof(float));
                pipe.InitBuffer(x2CastBuf_,  tileLen_ * sizeof(float));
                pipe.InitBuffer(x3CastBuf_,  tileLen_ * sizeof(float));
                pipe.InitBuffer(sCastBuf_,   tileLen_ * sizeof(float));
                pipe.InitBuffer(tmpBuf_,     tileLen_ * sizeof(float));
            } else {
                pipe.InitBuffer(tmpBuf_,     tileLen_ * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t blockStart, blockEnd;

            if (coreIdx < formerNum_) {
                blockStart = coreIdx * formerLength_;
                blockEnd = blockStart + formerLength_;
            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
                blockStart = formerNum_ * formerLength_;
                blockEnd = blockStart + tailLength_;
            } else {
                return;
            }

            int32_t curStart = blockStart;
            while (curStart < blockEnd) {
                int32_t curLen = tileLen_;
                if (curStart + curLen > blockEnd) {
                    curLen = blockEnd - curStart;
                }
                CopyIn(curStart, curLen);
                Compute(curLen);
                CopyOut(curStart, curLen);
                curStart += curLen;
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t start, int32_t length)
    {
        x1InLocal_ = inQueueX1_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[start], static_cast<uint32_t>(length));
        inQueueX1_.EnQue(x1InLocal_);

        x2InLocal_ = inQueueX2_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[start], static_cast<uint32_t>(length));
        inQueueX2_.EnQue(x2InLocal_);

        x3InLocal_ = inQueueX3_.AllocTensor<dataType>();
        LoadGmToUb(x3InLocal_, x3GM_[start], static_cast<uint32_t>(length));
        inQueueX3_.EnQue(x3InLocal_);

        sInLocal_ = inQueueS_.AllocTensor<dataType>();
        LoadGmToUb(sInLocal_, sGM_[start], static_cast<uint32_t>(length));
        inQueueS_.EnQue(sInLocal_);
    }

    __aicore__ inline void Compute(int32_t length)
    {
        x1InLocal_ = inQueueX1_.DeQue<dataType>();
        x2InLocal_ = inQueueX2_.DeQue<dataType>();
        x3InLocal_ = inQueueX3_.DeQue<dataType>();
        sInLocal_  = inQueueS_.DeQue<dataType>();
        yOutLocal_ = outQueue_.AllocTensor<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            // FP32 path: direct compute
            auto tmp = tmpBuf_.Get<float>();

            AscendC::Div(tmp, x2InLocal_, x3InLocal_, length);
            AscendC::Mul(tmp, tmp, sInLocal_, length);
            AscendC::Add(yOutLocal_, x1InLocal_, tmp, length);
        } else {
            // FP16/BF16 path: cast to fp32, compute, cast back
            auto x1f = x1CastBuf_.Get<float>();
            auto x2f = x2CastBuf_.Get<float>();
            auto x3f = x3CastBuf_.Get<float>();
            auto sf  = sCastBuf_.Get<float>();
            auto tmp = tmpBuf_.Get<float>();

            AscendC::Cast(x1f, x1InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(x2f, x2InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(x3f, x3InLocal_, AscendC::RoundMode::CAST_NONE, length);
            AscendC::Cast(sf,  sInLocal_,  AscendC::RoundMode::CAST_NONE, length);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Div(tmp, x2f, x3f, length);
            AscendC::Mul(tmp, tmp, sf, length);
            AscendC::Add(x1f, x1f, tmp, length);  // x1f = x1f + tmp (reuse)

            AscendC::Cast(yOutLocal_, x1f, AscendC::RoundMode::CAST_NONE, length);
            if constexpr (std::is_same_v<dataType, bfloat16_t>) {
                // Override for bf16: use CAST_ROUND
                AscendC::Cast(yOutLocal_, x1f, AscendC::RoundMode::CAST_ROUND, length);
            }
            AscendC::PipeBarrier<PIPE_V>();
        }

        outQueue_.EnQue<dataType>(yOutLocal_);

        inQueueX1_.FreeTensor(x1InLocal_);
        inQueueX2_.FreeTensor(x2InLocal_);
        inQueueX3_.FreeTensor(x3InLocal_);
        inQueueS_.FreeTensor(sInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t start, int32_t length)
    {
        yOutLocal_ = outQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(length));
        outQueue_.FreeTensor(yOutLocal_);
    }

private:
    AscendC::TPipe pipe;
    int32_t totalLen_;
    int32_t tileLen_;
    int32_t formerNum_;
    int32_t formerLength_;
    int32_t tailNum_;
    int32_t tailLength_;

    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> x3GM_;
    AscendC::GlobalTensor<dataType> sGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX1_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX2_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueX3_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueueS_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x3CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> x3InLocal_;
    AscendC::LocalTensor<dataType> sInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
};

// ---------------------------------------------------------------------------
// Kernel entries
// ---------------------------------------------------------------------------

extern "C" __global__ __aicore__ void foreach_addcdiv_list_fp16(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm,
    int32_t totalLength, int32_t tileLength,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    KernelForeachAddcdivList<half> kernel;
    kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                totalLength, tileLength, formerNum, formerLength, tailNum, tailLength);
    kernel.Process();
}

extern "C" __global__ __aicore__ void foreach_addcdiv_list_fp32(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm,
    int32_t totalLength, int32_t tileLength,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    KernelForeachAddcdivList<float> kernel;
    kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                totalLength, tileLength, formerNum, formerLength, tailNum, tailLength);
    kernel.Process();
}

extern "C" __global__ __aicore__ void foreach_addcdiv_list_bf16(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm,
    int32_t totalLength, int32_t tileLength,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    KernelForeachAddcdivList<bfloat16_t> kernel;
    kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                totalLength, tileLength, formerNum, formerLength, tailNum, tailLength);
    kernel.Process();
}
