125	// =========================================================================
126	// Strategy 1: single_row — one row at a time, for N <= 1024 and N <= 8192
127	// =========================================================================
128	
129	template <typename dataType>
130	class AddRmsNormSingleRowKernel {
131	public:
132	    __aicore__ inline void Init(
133	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR y, GM_ADDR rstd, GM_ADDR x_add,
134	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
135	        int32_t tasksPerCore, float eps, float invN)
136	    {
137	        this->M = M;
138	        this->N = N;
139	        this->blockM = blockM;
140	        this->usedCoreNum = usedCoreNum;
141	        this->tasksPerCore = tasksPerCore;
142	        this->eps = eps;
143	        this->invN = invN;
144	
145	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
146	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
147	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
148	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
149	        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstd), M);
150	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add), static_cast<uint64_t>(M) * N);
151	
152	        if ASCEND_IS_AIV {
153	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
154	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
155	            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
156	            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
157	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
158	            pipe.InitBuffer(rstdOutQueue_, BUFFER_NUM, sizeof(dataType));
159	            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
160	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
161	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
162	            pipe.InitBuffer(rstdBuf_, sizeof(float));
163	            if constexpr (!std::is_same_v<dataType, float>) {
164	                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
165	                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
166	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
167	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
168	            } else {
169	                // fp32: dedicated VECCALC buffer for intermediate computation,
170	                // avoiding full-aliasing Mul on VECOUT buffers
171	                pipe.InitBuffer(tmpBuf_, N * sizeof(float));
172	            }
173	
174	            gammaInLocal_ = gammaBuf_.Get<dataType>();
175	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
176	            AscendC::PipeBarrier<PIPE_MTE2>();
177	            AscendC::PipeBarrier<PIPE_ALL>();
178	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
179	        }
180	    }
181	
182	    __aicore__ inline void Process()
183	    {
184	        if ASCEND_IS_AIV {
185	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
186	            const int subBlockIdx = AscendC::GetSubBlockIdx();
187	
188	            for (int localIdx = 0; localIdx < this->tasksPerCore; ++localIdx) {
189	                const int bx = coreIdx * this->tasksPerCore + localIdx;
190	                if (bx >= BlockCountHelper(this->M, this->blockM)) {
191	                    continue;
192	                }
193	
194	                for (int row = 0; row < this->subBlockRows_; ++row) {
195	                    const int rowIdx = bx * this->blockM + subBlockIdx * this->subBlockRows_ + row;
196	                    if (rowIdx < this->M) {
197	                        this->ProcessRow(rowIdx);
198	                    }
199	                }
200	            }
201	        }
202	    }
203	
204	private:
205	    __aicore__ inline void CopyInX1(int32_t rowIdx)
206	    {
207	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
208	        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
209	        x1InQueue_.EnQue(x1InLocal_);
210	    }
211	
212	    __aicore__ inline void CopyInX2(int32_t rowIdx)
213	    {
214	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
215	        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
216	        x2InQueue_.EnQue(x2InLocal_);
217	    }
218	
219	    __aicore__ inline void CopyOutY(int32_t rowIdx)
220	    {
221	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
222	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
223	        yOutQueue_.FreeTensor(yOutLocal_);
224	    }
225	
226	    __aicore__ inline void CopyOutRstd(int32_t rowIdx)
227	    {
228	        rstdOutLocal_ = rstdOutQueue_.DeQue<dataType>();
229	        StoreUbToGm(rstdGM_[rowIdx], rstdOutLocal_, 1);
230	        rstdOutQueue_.FreeTensor(rstdOutLocal_);
231	    }
232	
233	    __aicore__ inline void CopyOutXAdd(int32_t rowIdx)
234	    {
235	        xAddOutLocal_ = xAddOutQueue_.DeQue<dataType>();
236	        StoreUbToGm(xAddGM_[static_cast<uint64_t>(rowIdx) * N], xAddOutLocal_, static_cast<uint32_t>(N));
237	        xAddOutQueue_.FreeTensor(xAddOutLocal_);
238	    }
239	
240	    __aicore__ inline void ComputeRow()
241	    {
242	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
243	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
244	        rstdOutLocal_ = rstdOutQueue_.AllocTensor<dataType>();
245	
246	        PrepareInvRmsTensorHelper<dataType>(rstdLocal_, rstdOutLocal_, rstdBuf_);
247	        reduceLocal_ = reduceBuf_.Get<float>();
248	        sumLocal_ = sumBuf_.Get<float>();
249	        if constexpr (std::is_same_v<dataType, float>) {
250	            tmpLocal_ = tmpBuf_.Get<float>();
251	        }
252	
253	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
254	        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, N);
255	
256	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
257	        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, N);
258	
259	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
260	
261	        // --- Step 1: x_add = x1 + x2 ---
262	        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
263	
264	        // --- Step 2: Output x_add ---
265	        if constexpr (std::is_same_v<dataType, float>) {
266	            // fp32: yLocal_=yOutLocal_, copy to separate xAddOutLocal_ buffer
267	            AscendC::Muls(xAddOutLocal_, yLocal_, 1.0f, N);
268	        } else {
269	            AscendC::Cast(xAddOutLocal_, yLocal_, OutputRoundModeHelper<dataType>(), N);
270	            AscendC::PipeBarrier<PIPE_V>();
271	        }
272	
273	        // --- Step 3: x_add^2 + ReduceSum (use tmpLocal_ for fp32 to avoid aliasing) ---
274	        if constexpr (std::is_same_v<dataType, float>) {
275	            AscendC::Mul(tmpLocal_, yLocal_, yLocal_, N);
276	            AscendC::ReduceSum<float>(sumLocal_, tmpLocal_, reduceLocal_, N);
277	        } else {
278	            AscendC::Mul(yLocal_, yLocal_, yLocal_, N);
279	            AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
280	        }
281	
282	        // --- Step 4: mean = sum/N + eps, rstd = 1/sqrt(mean) ---
283	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
284	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
285	        // Write Rsqrt to VECCALC tmpLocal_ to preserve float32 precision,
286	        // then read scalar and copy to output buffer.
287	        AscendC::Rsqrt(tmpLocal_, sumLocal_, 1);
288	        AscendC::PipeBarrier<PIPE_ALL>();
289	        float invRmsVal = tmpLocal_.GetValue(0);
290	        AscendC::PipeBarrier<PIPE_ALL>();
291	
292	        // Copy rstd from VECCALC tmpLocal_ to output
293	        if constexpr (std::is_same_v<dataType, float>) {
294	            AscendC::Muls(rstdLocal_, tmpLocal_, 1.0f, 1);
295	        } else {
296	            AscendC::Cast(rstdOutLocal_, tmpLocal_, OutputRoundModeHelper<dataType>(), 1);
297	            AscendC::PipeBarrier<PIPE_V>();
298	        }
299	
300	        // --- Step 5: Recompute x_add = x1 + x2 ---
301	        AscendC::Add(yLocal_, x1Local_, x2Local_, N);
302	
303	        // --- Step 6: x_add * rstd (use tmpLocal_ for fp32 to avoid aliasing) ---
304	        if constexpr (std::is_same_v<dataType, float>) {
305	            AscendC::Muls(tmpLocal_, yLocal_, invRmsVal, N);
306	            AscendC::Mul(yLocal_, tmpLocal_, gammaLocal_, N);
307	        } else {
308	            AscendC::Muls(yLocal_, yLocal_, invRmsVal, N);
309	            AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
310	        }
311	
312	        // --- Step 7: Output y ---
313	        if constexpr (!std::is_same_v<dataType, float>) {
314	            AscendC::Cast(yOutLocal_, yLocal_, OutputRoundModeHelper<dataType>(), N);
315	            AscendC::PipeBarrier<PIPE_V>();
316	        }
317	        // fp32: yLocal_ IS yOutLocal_, output is already there
318	
319	        x1InQueue_.FreeTensor(x1InLocal_);
320	        x2InQueue_.FreeTensor(x2InLocal_);
321	        yOutQueue_.EnQue(yOutLocal_);
322	        rstdOutQueue_.EnQue(rstdOutLocal_);
323	        xAddOutQueue_.EnQue(xAddOutLocal_);
324	    }

