#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_addcdiv_list.h"

namespace ascend_kernel {

constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
constexpr int64_t kCacheLineSize = 512;

at::Tensor foreach_addcdiv_list(
    const at::Tensor &x1, const at::Tensor &x2,
    const at::Tensor &x3, const at::Tensor &scalars)
{
    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
                   x1.scalar_type() == at::kBFloat16,
        "unsupported dtype");
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type() &&
                   x1.scalar_type() == x3.scalar_type() &&
                   x1.scalar_type() == scalars.scalar_type(),
        "all inputs must have the same dtype");
    TORCH_CHECK(x1.numel() == x2.numel(), "numel mismatch");
    TORCH_CHECK(x1.numel() == x3.numel(), "numel mismatch");
    TORCH_CHECK(x1.numel() == scalars.numel(), "numel mismatch");

    auto x1Contig = x1.contiguous();
    auto x2Contig = x2.contiguous();
    auto x3Contig = x3.contiguous();
    auto sContig = scalars.contiguous();

    auto dtype = x1.scalar_type();
    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    coreNum = std::min<int32_t>(coreNum, DEFAULT_NUM_PHYSICAL_CORES);
    if (coreNum <= 0) coreNum = 1;

    uint64_t ubSizeVal;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
    int64_t ubSize = static_cast<int64_t>(ubSizeVal);

    int64_t totalLen = x1Contig.numel();
    int32_t dtypeSize = static_cast<int32_t>(c10::elementSize(dtype));

    // Tile size calculation:
    // fp16/bf16: 5 VECIN/VECOUT(fp16) + 5 Cast VECCALC(fp32) = 5*2+5*4=30 bytes/elem
    // fp32: 5 VECIN/VECOUT(fp32) + 1 tmp VECCALC(fp32) = 6*4=24 bytes/elem
    int64_t bytesPerElem = (dtype == at::kFloat) ? 24 : 30;
    int64_t kDataUbBudget = ubSize * 3 / 10;  // ~30% of UB, conservative
    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / bytesPerElem);
    tileLen = (tileLen / 32) * 32;
    if (tileLen < 32) tileLen = 32;
    if (tileLen > 4096) tileLen = 4096;

    // Block-level partition with cache line alignment
    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
    if (elemPerCL < 1) elemPerCL = 256;
    int32_t elemsPerBlock = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
    elemsPerBlock = ((elemsPerBlock + elemPerCL - 1) / elemPerCL) * elemPerCL;
    if (elemsPerBlock < elemPerCL) elemsPerBlock = elemPerCL;

    int32_t formerNum = static_cast<int32_t>(totalLen / elemsPerBlock);
    int32_t formerLen = elemsPerBlock;
    int32_t tailLen = static_cast<int32_t>(totalLen % elemsPerBlock);
    int32_t tailNum = (tailLen > 0) ? 1 : 0;

    int32_t numTilesPerBlock = static_cast<int32_t>((elemsPerBlock + tileLen - 1) / tileLen);

    auto yOut = at::empty_like(x1Contig);

    // All params as left values for EXEC_KERNEL_CMD
    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
    uint32_t blockDim = static_cast<uint32_t>(formerNum + tailNum);

    EXEC_KERNEL_CMD(foreach_addcdiv_list, blockDim,
                    x1Contig, x2Contig, x3Contig, sContig, yOut,
                    totalLenI32, tileLen,
                    formerNum, formerLen, tailNum, tailLen,
                    elemsPerBlock, numTilesPerBlock, dtypeFlag);

    return yOut;
}

}  // namespace ascend_kernel
