 */

// ForeachAddcdivList: Y = X1 + X2 / X3 * Scalars
// Adapted from working AddRmsNorm kernel pattern.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    // CAST_ROUND: round to nearest even for float→half/bfloat16
    return AscendC::RoundMode::CAST_ROUND;
}

template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename dataType>
class KernelForeachAddcdivList {
public:
    __aicore__ inline void Init(
        GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
        GM_ADDR scalarsGm, GM_ADDR yGm,
        int32_t totalLength, int32_t tileLength,
        int32_t formerNum, int32_t formerLength,
        int32_t tailNum, int32_t tailLength,
        int32_t elementsPerBlock, int32_t numTilesPerBlock)
    {
        totalLen_ = totalLength;
        N_ = tileLength;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailNum_ = tailNum;
        tailLength_ = tailLength;
        elemsPerBlock_ = elementsPerBlock;
        tilesPerBlock_ = numTilesPerBlock;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Gm), totalLen_);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Gm), totalLen_);
        x3GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x3Gm), totalLen_);
        sGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(scalarsGm), totalLen_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalLen_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(x3InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(sInQueue_,  BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N_ * sizeof(dataType));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(x1CastBuf_, N_ * sizeof(float));
                pipe.InitBuffer(x2CastBuf_, N_ * sizeof(float));
                pipe.InitBuffer(x3CastBuf_, N_ * sizeof(float));
                pipe.InitBuffer(sCastBuf_,  N_ * sizeof(float));
                pipe.InitBuffer(yCastBuf_,  N_ * sizeof(float));
            }
            pipe.InitBuffer(tmpBuf_, N_ * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t blockOffset;

            if (coreIdx < formerNum_) {
                blockOffset = coreIdx * formerLength_;
            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
                blockOffset = formerNum_ * formerLength_;
            } else {
                return;
            }

            int32_t blockEnd = blockOffset + elemsPerBlock_;
            if (blockEnd > totalLen_) blockEnd = totalLen_;

            for (int32_t t = 0; t < tilesPerBlock_; ++t) {
                int32_t tileStart = blockOffset + t * N_;
                if (tileStart >= blockEnd) break;
                int32_t curLen = N_;
                if (tileStart + curLen > totalLen_) {
                    curLen = totalLen_ - tileStart;
                }
                if (tileStart + curLen > blockEnd) {
                    curLen = blockEnd - tileStart;
                }
                if (curLen <= 0) break;

                CopyIn(tileStart, curLen);
                Compute(curLen);
                CopyOut(tileStart, curLen);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t start, int32_t count)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[start], static_cast<uint32_t>(count));
        x1InQueue_.EnQue(x1InLocal_);

        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[start], static_cast<uint32_t>(count));
        x2InQueue_.EnQue(x2InLocal_);

        x3InLocal_ = x3InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x3InLocal_, x3GM_[start], static_cast<uint32_t>(count));
        x3InQueue_.EnQue(x3InLocal_);

        sInLocal_ = sInQueue_.AllocTensor<dataType>();
        LoadGmToUb(sInLocal_, sGM_[start], static_cast<uint32_t>(count));
        sInQueue_.EnQue(sInLocal_);
    }

    __aicore__ inline void Compute(int32_t count)
    {
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();
        x3InLocal_ = x3InQueue_.DeQue<dataType>();
        sInLocal_  = sInQueue_.DeQue<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            auto tmp = tmpBuf_.Get<float>();
            AscendC::Div(tmp, x2InLocal_, x3InLocal_, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(tmp, tmp, sInLocal_, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(tmp, x1InLocal_, tmp, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Muls(yOutLocal_, tmp, 1.0f, count);
            AscendC::PipeBarrier<PIPE_V>();
        } else {
            PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, count);
            PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, count);
            PrepareInputTensorHelper<dataType>(x3Local_, x3InLocal_, x3CastBuf_, count);
            PrepareInputTensorHelper<dataType>(sLocal_,  sInLocal_,  sCastBuf_,  count);

            AscendC::Div(x2Local_, x2Local_, x3Local_, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(x2Local_, x2Local_, sLocal_, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(x1Local_, x1Local_, x2Local_, count);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Cast(yOutLocal_, x1Local_, OutputRoundModeHelper<dataType>(), count);
            AscendC::PipeBarrier<PIPE_V>();
        }

        yOutQueue_.EnQue(yOutLocal_);

        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
        x3InQueue_.FreeTensor(x3InLocal_);
        sInQueue_.FreeTensor(sInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t start, int32_t count)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(count));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

private:
    AscendC::TPipe pipe;
    int32_t totalLen_;
    int32_t N_;
    int32_t formerNum_;
    int32_t formerLength_;
    int32_t tailNum_;
    int32_t tailLength_;
    int32_t elemsPerBlock_;
    int32_t tilesPerBlock_;

    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<dataType> x3GM_;
    AscendC::GlobalTensor<dataType> sGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x3InQueue_;
    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> sInQueue_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> yOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x3CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> x3InLocal_;
    AscendC::LocalTensor<dataType> sInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;

    AscendC::LocalTensor<float> x1Local_;
    AscendC::LocalTensor<float> x2Local_;
    AscendC::LocalTensor<float> x3Local_;
    AscendC::LocalTensor<float> sLocal_;
};

extern "C" __global__ __aicore__ void foreach_addcdiv_list(
    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
    GM_ADDR scalarsGm, GM_ADDR yGm,
    int32_t totalLength, int32_t tileLength,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength,
    int32_t elementsPerBlock, int32_t numTilesPerBlock,
    int32_t dtypeFlag)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);

    if (dtypeFlag == 0) {
        KernelForeachAddcdivList<float> kernel;
        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelForeachAddcdivList<half> kernel;
        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
        kernel.Process();
    } else {
        KernelForeachAddcdivList<bfloat16_t> kernel;
        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
        kernel.Process();
    }
}
